template <typename UnionPtrType>
UrlRequestActionPtr UrlRequestAction::Clone() const {
  switch (tag_) {
    case Tag::kAddHeaders:
      return NewAddHeaders(
          mojo::Clone(data_.add_headers));
    case Tag::kRemoveHeader:
      return NewRemoveHeader(
          mojo::Clone(data_.remove_header));
    case Tag::kSubstituteQueryPattern:
      return NewSubstituteQueryPattern(
          mojo::Clone(data_.substitute_query_pattern));
    case Tag::kReplaceUrl:
      return NewReplaceUrl(
          mojo::Clone(data_.replace_url));
    case Tag::kAppendToQuery:
      return NewAppendToQuery(
          mojo::Clone(data_.append_to_query));
    case Tag::kPolicy:
      return NewPolicy(
          mojo::Clone(data_.policy));
  }
  return nullptr;
}

template <typename T,
          typename std::enable_if<std::is_same<
              T, UrlRequestAction>::value>::type*>
bool UrlRequestAction::Equals(const T& other) const {
  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::kAddHeaders:
      return mojo::Equals(data_.add_headers, other.data_.add_headers);
    case Tag::kRemoveHeader:
      return mojo::Equals(data_.remove_header, other.data_.remove_header);
    case Tag::kSubstituteQueryPattern:
      return mojo::Equals(data_.substitute_query_pattern, other.data_.substitute_query_pattern);
    case Tag::kReplaceUrl:
      return mojo::Equals(data_.replace_url, other.data_.replace_url);
    case Tag::kAppendToQuery:
      return mojo::Equals(data_.append_to_query, other.data_.append_to_query);
    case Tag::kPolicy:
      return mojo::Equals(data_.policy, other.data_.policy);
  }

  return false;
}
